package com.example.starter.support;

/**
 * 安全评估与资格规则限值常量；所有边界均为闭区间，恰等限值通过。
 */
public final class Limits {

    /** 相邻站点最小间距（米），恰等通过 */
    public static final int MIN_STOP_DISTANCE_M = 500;
    /** 相邻站点最大间距（米），恰等通过 */
    public static final int MAX_STOP_DISTANCE_M = 3000;
    /** 道路等级下限，恰等通过 */
    public static final int MIN_ROAD_GRADE = 3;
    /** 车辆座位数上限，恰等通过 */
    public static final int MAX_VEHICLE_SEATS = 56;
    /** 资格有效期（年） */
    public static final int QUALIFICATION_YEARS = 1;
    /** 续期窗口：到期前 30 日内（含恰第 30 日与到期当日） */
    public static final int RENEWAL_WINDOW_DAYS = 30;

    private Limits() {
    }
}

package com.example.starter.support;

/**
 * 业务冲突（HTTP 409）：幂等同键异参、同线路同日期重复评估、车辆已被执行中线路占用等。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.support;

/**
 * 业务规则不满足（HTTP 422）：如续期不在受理窗口内、资格已失效等。
 */
public class BusinessException extends RuntimeException {

    public BusinessException(String message) {
        super(message);
    }
}

package com.example.starter.support;

/**
 * 资源不存在（HTTP 404）。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.support;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.List;

/**
 * 幂等指纹工具：覆盖 requestId 与全部业务字段，字段按固定顺序拼接后取 SHA-256。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算指纹。fields 须包含 requestId 及全部业务字段（调用方保证顺序固定）。
     */
    public static String of(List<String> fields) {
        String canonical = String.join("|", fields);
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(canonical.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 应用基础配置：统一使用 UTC 时钟，测试中可替换为可控时钟。
 */
@Configuration
public class AppConfig {

    /**
     * 业务时钟（UTC 日界判定均基于此时钟）。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}

